//! `sermofur_core::instance::read_configuration` against the table that the .NET code produced
//! (`rust/tests/golden/instance-config.json`, regenerated by `rust/tools/config-oracle`).

use std::path::{Path, PathBuf};
#[cfg(windows)]
use std::process::Command;
use std::sync::OnceLock;

use proptest::prelude::*;
use serde_json::Value;
use sermofur_core::error::SermofurError;
use sermofur_core::instance::{CONFIGURATION_FILE, MARKER, read_configuration};
use uuid::Uuid;

const VALID: &str = r#"{"schemaVersion":2,"instanceId":"6f1c2b3a-4d5e-4f60-8a7b-9c0d1e2f3a4b","createdAt":"2026-11-06T11:00:00Z"}"#;

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/instance-config.json"
    );
    let text = std::fs::read_to_string(path).expect("the golden file exists");
    serde_json::from_str(&text).expect("the golden file is valid JSON")
}

/// The temporary directory with every link of its path resolved: `reject_links` refuses links
/// on purpose, and on macOS the temporary directory is under `/var`, a link to `/private/var`
/// (the .NET suite does the same in `TestInstance`). On Windows `canonicalize` would add the
/// `\\?\` prefix, so the directory is kept as it is.
fn temp_base() -> &'static Path {
    static BASE: OnceLock<PathBuf> = OnceLock::new();
    BASE.get_or_init(|| {
        let dir = std::env::temp_dir();
        if cfg!(windows) {
            dir
        } else {
            std::fs::canonicalize(dir).expect("the temporary directory resolves")
        }
    })
}

fn base64(text: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0);
    for b in text.bytes().filter(|b| *b != b'=') {
        let v = match b {
            b'A'..=b'Z' => b - b'A',
            b'a'..=b'z' => b - b'a' + 26,
            b'0'..=b'9' => b - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("not base64"),
        };
        acc = (acc << 6) | u32::from(v);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(u8::try_from((acc >> bits) & 0xFF).expect("a byte"));
        }
    }
    out
}

/// A fresh root with its `.sermofur` folder, removed on drop.
struct TempRoot(PathBuf);

impl TempRoot {
    fn new(content: Option<&[u8]>) -> Self {
        let root = temp_base().join(format!("sermofur-instance-{}", Uuid::new_v4()));
        let marker = root.join(MARKER);
        std::fs::create_dir_all(&marker).expect("temp root");
        if let Some(content) = content {
            std::fs::write(marker.join(CONFIGURATION_FILE), content).expect("write");
        }
        Self(root)
    }
}

impl Drop for TempRoot {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// Compares one outcome with the golden one; the mismatch is returned, not raised.
fn compare(root: &Path, allow_legacy: bool, expected: &Value) -> Result<(), String> {
    let local = expected["localOffsetMinutes"].as_i64().unwrap_or(60);
    let local = i16::try_from(local).expect("a small offset");
    let actual = read_configuration(root, allow_legacy, |_| local);
    if let Some(code) = expected["code"].as_str() {
        let want = SermofurError::new(
            code,
            expected["message"].as_str().expect("a message"),
            i32::try_from(expected["exitCode"].as_i64().expect("an exit code")).expect("i32"),
        );
        return match actual {
            Err(e) if e == want => Ok(()),
            other => Err(format!("expected {want}, got {other:?}")),
        };
    }
    let got = actual.map_err(|e| format!("expected values, got error {e}"))?;
    let want = (
        expected["schemaVersion"].as_i64().expect("schema"),
        expected["instanceId"].as_str().expect("id").to_owned(),
        expected["createdAtUtcTicks"]
            .as_str()
            .expect("ticks")
            .to_owned(),
        expected["createdAtOffsetMinutes"].as_i64().expect("offset"),
    );
    let have = (
        i64::from(got.schema_version),
        got.instance_id.to_string(),
        got.created_at.utc_ticks().to_string(),
        i64::from(got.created_at.offset_minutes()),
    );
    if have == want {
        Ok(())
    } else {
        Err(format!("expected {want:?}, got {have:?}"))
    }
}

#[test]
fn every_case_matches_the_oracle_in_both_modes() {
    let golden = golden();
    let cases = golden["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 111);
    let mut mismatches = Vec::new();
    for case in cases {
        let name = case["name"].as_str().expect("a name");
        let content = case["content"].as_str().map(base64);
        let root = TempRoot::new(content.as_deref());
        if name == "instance_json_is_directory" {
            std::fs::create_dir(root.0.join(MARKER).join(CONFIGURATION_FILE)).expect("directory");
        }
        for (mode, legacy) in [("strict", false), ("legacy", true)] {
            if let Err(reason) = compare(&root.0, legacy, &case[mode]) {
                mismatches.push(format!("{name} ({mode}): {reason}"));
            }
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

/// Makes `link` point to the directory `target`. On Windows it is a junction (`mklink /J`, no
/// privilege needed); elsewhere a symbolic link.
fn directory_link(link: &Path, target: &Path) {
    #[cfg(windows)]
    {
        let status = Command::new("cmd")
            .args(["/C", "mklink", "/J"])
            .arg(link)
            .arg(target)
            .output()
            .expect("cmd runs");
        assert!(status.status.success(), "mklink /J failed: {status:?}");
    }
    #[cfg(not(windows))]
    std::os::unix::fs::symlink(target, link).expect("symlink");
}

fn remove_directory_link(link: &Path) {
    // `remove_dir` removes a junction or a directory symlink without touching the target.
    let _ = std::fs::remove_dir(link).or_else(|_| std::fs::remove_file(link));
}

fn assert_unsafe_path(result: sermofur_core::error::Result<impl std::fmt::Debug>) {
    let error = result.expect_err("a link is refused");
    assert_eq!((error.code.as_str(), error.exit_code), ("unsafe_path", 4));
}

#[test]
fn a_link_in_an_ancestor_is_unsafe_path() {
    let real = TempRoot::new(Some(VALID.as_bytes()));
    assert!(read_configuration(&real.0, false, |_| 0).is_ok(), "control");
    let link = temp_base().join(format!("sermofur-link-{}", Uuid::new_v4()));
    directory_link(&link, &real.0);
    let result = read_configuration(&link, false, |_| 0);
    remove_directory_link(&link);
    assert_unsafe_path(result);
}

#[test]
fn a_link_on_the_marker_folder_is_unsafe_path() {
    let real = TempRoot::new(Some(VALID.as_bytes()));
    let root = TempRoot::new(None);
    let marker = root.0.join(MARKER);
    std::fs::remove_dir(&marker).expect("empty marker");
    directory_link(&marker, &real.0.join(MARKER));
    let result = read_configuration(&root.0, false, |_| 0);
    remove_directory_link(&marker);
    assert_unsafe_path(result);
}

/// Creating a symbolic link on Windows needs developer mode or a privilege: when it is
/// refused, the test says so and stops (the junction tests above never skip).
fn file_symlink(link: &Path, target: &Path) -> bool {
    #[cfg(windows)]
    let made = std::os::windows::fs::symlink_file(target, link);
    #[cfg(not(windows))]
    let made = std::os::unix::fs::symlink(target, link);
    if let Err(error) = &made {
        eprintln!("file symlink creation refused ({error}); symlink case skipped");
    }
    made.is_ok()
}

#[test]
fn a_file_symlink_for_instance_json_is_unsafe_path() {
    let real = TempRoot::new(Some(VALID.as_bytes()));
    let root = TempRoot::new(None);
    let file = root.0.join(MARKER).join(CONFIGURATION_FILE);
    if !file_symlink(&file, &real.0.join(MARKER).join(CONFIGURATION_FILE)) {
        return;
    }
    assert_unsafe_path(read_configuration(&root.0, false, |_| 0));
}

#[cfg(windows)]
#[test]
fn a_directory_symlink_is_unsafe_path() {
    let real = TempRoot::new(Some(VALID.as_bytes()));
    let link = temp_base().join(format!("sermofur-symlink-{}", Uuid::new_v4()));
    if let Err(error) = std::os::windows::fs::symlink_dir(&real.0, &link) {
        eprintln!("directory symlink creation refused ({error}); symlink case skipped");
        return;
    }
    let result = read_configuration(&link, false, |_| 0);
    remove_directory_link(&link);
    assert_unsafe_path(result);
    assert!(sermofur_core::instance::reject_links(&real.0).is_ok());
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(32))]
    #[test]
    fn arbitrary_files_never_panic(bytes in proptest::collection::vec(any::<u8>(), 0..=512)) {
        let root = TempRoot::new(Some(&bytes));
        let _ = read_configuration(&root.0, true, |_| 60);
    }
}
